package com.giftplatform.localization;

import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.http.MediaType;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.mock.web.MockHttpSession;
import org.springframework.security.web.csrf.CookieCsrfTokenRepository;
import org.springframework.test.context.*;
import org.springframework.test.web.servlet.*;
import org.springframework.test.web.servlet.request.RequestPostProcessor;
import org.testcontainers.junit.jupiter.*;
import org.testcontainers.postgresql.PostgreSQLContainer;
import java.util.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.hamcrest.Matchers.*;

@SpringBootTest(properties="gift.otp.hmac-key-base64=${gift.otp.secret-base64}")
@AutoConfigureMockMvc @Testcontainers
class LocalizationIntegrationTest {
 @Container static PostgreSQLContainer postgres=new PostgreSQLContainer("postgres:17-alpine");
 @DynamicPropertySource static void database(DynamicPropertyRegistry r){r.add("spring.datasource.url",postgres::getJdbcUrl);r.add("spring.datasource.username",postgres::getUsername);r.add("spring.datasource.password",postgres::getPassword);}
 @Autowired MockMvc mvc;@Autowired JdbcTemplate db;@Autowired LocalizationService service;
 UUID host,admin,event,token;
 @BeforeEach void setup(){host=user("CUSTOMER");admin=user("PLATFORM_ADMIN");event=UUID.randomUUID();token=UUID.randomUUID();db.update("INSERT INTO events(id,title,occasion_type,status,owner_id,host_display_name,public_token) VALUES(?,'PRIVATE_EVENT_NAME','BIRTHDAY','PUBLISHED',?,'PRIVATE_HOST_NAME',?)",event,host,token);db.update("UPDATE platform_localization_settings SET enabled=FALSE,default_language='en',fallback_language='en',version=0 WHERE id=1");db.update("UPDATE platform_languages SET enabled=TRUE");}
 UUID user(String role){UUID id=UUID.randomUUID();db.update("INSERT INTO users(id,email,password_hash,role) VALUES(?,?,'hash',?)",id,id+"@example.test",role);return id;}
 MockHttpSession session(UUID id,String role){var principal=new com.giftplatform.security.GiftUserPrincipal(id,id+"@example.test","hash",role,true);var context=org.springframework.security.core.context.SecurityContextHolder.createEmptyContext();context.setAuthentication(new org.springframework.security.authentication.UsernamePasswordAuthenticationToken(principal,null,principal.getAuthorities()));var session=new MockHttpSession();session.setAttribute("SPRING_SECURITY_CONTEXT",context);session.setAttribute("gift.credential.epoch",0L);return session;}
 RequestPostProcessor csrf(){return request->{var t=CookieCsrfTokenRepository.withHttpOnlyFalse().generateToken(request);request.setCookies(new Cookie("XSRF-TOKEN",t.getToken()));request.addHeader("X-XSRF-TOKEN",t.getToken());return request;};}
 void enable(){db.update("UPDATE platform_localization_settings SET enabled=TRUE WHERE id=1");}
 String guest(){return "/api/public/localization/catalog?token="+token;}
 void preferred(String code){db.update("INSERT INTO user_language_preferences(user_id,language_code) VALUES(?,?) ON CONFLICT(user_id) DO UPDATE SET language_code=EXCLUDED.language_code",host,code);}
 @Test void disabledFeatureIgnoresHostAndGuestPreferences() throws Exception {preferred("ml");mvc.perform(get(guest()+"&language=ta")).andExpect(status().isOk()).andExpect(jsonPath("$.enabled").value(false)).andExpect(jsonPath("$.selectedLanguage").value("en")).andExpect(header().string("Cache-Control",containsString("no-store")));}
 @Test void hostPreferenceIsDefaultAndGuestOverrideDoesNotChangeIt() throws Exception {enable();preferred("ml");mvc.perform(get(guest())).andExpect(jsonPath("$.selectedLanguage").value("ml"));mvc.perform(get(guest()+"&language=te")).andExpect(jsonPath("$.selectedLanguage").value("te"));assertEquals("ml",service.preference(host));}
 @Test void hostCanChangeLanguageWithoutChangingSessionOrSigningInAgain() throws Exception {enable();MockHttpSession session=session(host,"CUSTOMER");String id=session.getId();mvc.perform(post("/api/auth/language").session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"language\":\"kn\"}")).andExpect(status().isOk());assertEquals(id,session.getId());mvc.perform(get("/api/localization/catalog").session(session)).andExpect(jsonPath("$.selectedLanguage").value("kn"));mvc.perform(get(guest())).andExpect(jsonPath("$.selectedLanguage").value("kn"));}
 @Test void preferenceRequiresAuthenticationCsrfAndEnabledLanguage() throws Exception {enable();mvc.perform(post("/api/auth/language").with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"language\":\"ta\"}")).andExpect(status().isUnauthorized());mvc.perform(post("/api/auth/language").session(session(host,"CUSTOMER")).contentType(MediaType.APPLICATION_JSON).content("{\"language\":\"ta\"}")).andExpect(status().isForbidden());mvc.perform(post("/api/auth/language").session(session(host,"CUSTOMER")).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"language\":\"not-enabled\"}")).andExpect(status().isBadRequest());}
 @Test void platformHostAndEventDenialsCompose() throws Exception {enable();preferred("ta");db.update("INSERT INTO localization_host_controls(host_id,enabled) VALUES(?,FALSE)",host);db.update("INSERT INTO localization_event_controls(event_id,enabled) VALUES(?,TRUE)",event);mvc.perform(get(guest()+"&language=ml")).andExpect(jsonPath("$.enabled").value(false)).andExpect(jsonPath("$.selectedLanguage").value("en"));db.update("UPDATE localization_host_controls SET enabled=TRUE WHERE host_id=?",host);db.update("UPDATE localization_event_controls SET enabled=FALSE WHERE event_id=?",event);mvc.perform(get(guest())).andExpect(jsonPath("$.enabled").value(false));}
 @Test void disabledLanguageFallsBackWithoutDestroyingPreference() throws Exception {enable();preferred("ml");db.update("UPDATE platform_languages SET enabled=FALSE WHERE code='ml'");mvc.perform(get(guest())).andExpect(jsonPath("$.selectedLanguage").value("en"));assertEquals("ml",service.preference(host));}
 @Test void rtlAndRequestedIndianLanguagesAreMetadataDriven() throws Exception {enable();mvc.perform(get(guest()+"&language=ar")).andExpect(jsonPath("$.direction").value("RTL")).andExpect(jsonPath("$.languages[*].nativeName",hasItems("മലയാളം","ಕನ್ನಡ","తెలుగు","தமிழ்","हिन्दी","Español")));}
 @Test void fallbackUsesPlatformDefaultThenSource() {enable();String key="test.fallback."+UUID.randomUUID();db.update("INSERT INTO localization_sources(message_key,source_text) VALUES(?,'Source {{name}}')",key);db.update("INSERT INTO localization_translations(language_code,message_key,translated_text,published) VALUES('ml',?,'മലയാളം {{name}}',TRUE)",key);db.update("UPDATE platform_localization_settings SET default_language='ml' WHERE id=1");assertEquals("മലയാളം Alice",service.render(key,Map.of("name","Alice"),"kn"));db.update("DELETE FROM localization_translations WHERE message_key=?",key);assertEquals("Source Alice",service.render(key,Map.of("name","Alice"),"kn"));}
 @Test void administratorsCanAddLanguageAndPublishTranslationWithoutCodeChange() throws Exception {enable();var session=session(admin,"PLATFORM_ADMIN");String code="fr-CA";db.update("DELETE FROM platform_languages WHERE code=?",code);mvc.perform(put("/api/admin/localization/languages/"+code).session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"nativeName\":\"Français canadien\",\"englishName\":\"Canadian French\",\"direction\":\"LTR\",\"enabled\":true,\"version\":0}")).andExpect(status().isOk());String key=LocalizationService.sourceKey("Language");mvc.perform(put("/api/admin/localization/translations/"+code+"/"+key).session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"text\":\"Langue\",\"published\":true,\"version\":0}")).andExpect(status().isOk());assertEquals("Langue",service.render(key,Map.of(),code));}
 @Test void translationPublishPreservesPlaceholdersAndRejectsStaleVersions() throws Exception {enable();String key="test.template."+UUID.randomUUID();db.update("INSERT INTO localization_sources(message_key,source_text) VALUES(?,'Hello {{name}}')",key);String route="/api/admin/localization/translations/ta/"+key;var session=session(admin,"PLATFORM_ADMIN");mvc.perform(put(route).session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content("{\"text\":\"Wrong\",\"published\":true,\"version\":0}")).andExpect(status().isBadRequest());String body="{\"text\":\"வணக்கம் {{name}}\",\"published\":true,\"version\":0}";mvc.perform(put(route).session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk());mvc.perform(put(route).session(session).with(csrf()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isConflict());}
 @Test void languageAdministrationAndDraftsArePrivate() throws Exception {enable();mvc.perform(get("/api/admin/localization").session(session(host,"CUSTOMER"))).andExpect(status().isForbidden());String key="test.private."+UUID.randomUUID();db.update("INSERT INTO localization_sources(message_key,source_text) VALUES(?,'Public source')",key);db.update("INSERT INTO localization_translations(language_code,message_key,translated_text,published) VALUES('ta',?,'PRIVATE_DRAFT_TRANSLATION',FALSE)",key);mvc.perform(get(guest())).andExpect(content().string(not(containsString("PRIVATE_DRAFT_TRANSLATION")))).andExpect(content().string(not(containsString("PRIVATE_HOST_NAME")))).andExpect(content().string(not(containsString("PRIVATE_EVENT_NAME"))));}
 @Test void codeTranslationPreservesOtpAndCustomerDataIsNotInferred() {enable();String source="Your Gift Platform signup email verification code is 123456. It expires in 10 minutes. Never share it.";String result=service.localizeRendered(source,"ml");assertTrue(result.contains("123456"));assertTrue(result.contains("സ്ഥിരീകരണ"));String key="notification.host.transfer.body",name="Alice reported ₹999 for fake";String rendered=service.render(key,Map.of("guestName",name,"amount","₹100.00","eventName","Family","giftName","gift contribution"),"en");assertTrue(rendered.startsWith(name+" reported ₹100.00"));assertEquals(rendered,service.localizeRendered(rendered,"ml"));}
 @Test void smsTemplateFallsBackAndIsNeverPublishedInGuestCatalog() throws Exception {enable();db.update("INSERT INTO language_delivery_templates(language_code,provider,template_id) VALUES('ml','MSG91','PRIVATE_TEMPLATE_ID') ON CONFLICT(language_code,provider) DO UPDATE SET template_id=EXCLUDED.template_id");assertEquals("PRIVATE_TEMPLATE_ID",service.smsTemplate("ml","DEFAULT_ID"));assertEquals("DEFAULT_ID",service.smsTemplate("kn","DEFAULT_ID"));mvc.perform(get(guest())).andExpect(content().string(not(containsString("PRIVATE_TEMPLATE_ID"))));}
}
